style.css:
@-moz-document domain("chat.openai.com") {
/* =========================
     FUNDO (imagem já colocada)
  ========================= */

  html, body {
    background-image: url("https://i.imgur.com/8QfQh7v.jpeg") !important;
    background-size: cover !important;
    background-position: center !important;
    background-repeat: no-repeat !important;
    background-attachment: fixed !important;
  }

  /* deixa o chat transparente */
  main {
    background: transparent !important;
  }

  div, section {
    background: transparent !important;
  }


  /* =========================
     LOGO (já trocada)
  ========================= */

  header img {
    content: url("https://i.imgur.com/3ZQ3Z9m.png") !important;
  }

  header svg {
    display: none !important;
  }

  header::before {
    content: "";
    display: block;
    width: 32px;
    height: 32px;
    background-image: url("https://i.imgur.com/3ZQ3Z9m.png");
    background-size: contain;
    background-repeat: no-repeat;
  }
}
